/* From Uiverse.io by gharsh11032000  - Tags: card, hover, hover effect, card template, cool card, cardhover , card animation, card hover */
.__UIV_SCOPE__ .card {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 320px;
  border-radius: 24px;
  line-height: 1.6;
  transition: all 0.64s cubic-bezier(0.23, 1, 0.32, 1);
}
.__UIV_SCOPE__ .content {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 24px;
  padding: 36px;
  border-radius: 24px;
  background: transparent;
  color: #000000;
  z-index: 1;
  transition: all 0.64s cubic-bezier(0.23, 1, 0.32, 1);
}
.__UIV_SCOPE__ .card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  background-color: #0a3cff;
  border-radius: inherit;
  height: 100%;
  width: 100%;
  opacity: 0;
  transform: skew(-24deg);
  clip-path: circle(0% at 50% 50%);
  transition: all 0.64s cubic-bezier(0.23, 1, 0.32, 1);
}
.__UIV_SCOPE__ .content .heading {
  font-weight: 700;
  font-size: 36px;
  line-height: 1.3;
  z-index: 1;
}
.__UIV_SCOPE__ .content .para {
  z-index: 1;
  opacity: 0.8;
  font-size: 18px;
}
.__UIV_SCOPE__ .content .para-sm {
  font-size: 16px;
}
.__UIV_SCOPE__ .card:hover::before {
  opacity: 1;
  transform: skew(0deg);
  clip-path: circle(140.9% at 0 0);
}
.__UIV_SCOPE__ .card:hover .content {
  color: #ffffff;
}
